package com.safebaba.controller;
import com.safebaba.model.*; import com.safebaba.repository.*; import com.safebaba.service.UsuarioService;
import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
import java.time.LocalDate; import java.time.LocalDateTime; import java.util.*;
@RestController @RequestMapping("/api/assinatura")
public class AssinaturaController {
 private final AssinaturaPaiRepository repo; private final PaiRepository pais; private final UsuarioService usuarios; private final AgendamentoRepository agendamentos;
 public AssinaturaController(AssinaturaPaiRepository r,PaiRepository p,UsuarioService u,AgendamentoRepository ag){repo=r;pais=p;usuarios=u;agendamentos=ag;}
 private PaiResponsavel pai(String email){Usuario u=usuarios.porEmail(email); if(u.getTipo()!=TipoUsuario.PAI) throw new AccessDeniedException("Assinatura disponível apenas para responsáveis."); return pais.findByUsuarioId(u.getId()).orElseThrow(()->new IllegalArgumentException("Perfil de responsável não encontrado."));}
 @GetMapping("/planos") public List<Map<String,Object>> planos(){return List.of(plano("GRATUITO","Gratuito",0,0,"Até 1 agendamento ativo por vez","Favoritos e avaliações"),plano("FAMILIA","Família",29.90,5,"Até 5 agendamentos por mês","Histórico ampliado e suporte prioritário"),plano("FAMILIA_PLUS","Família+",59.90,10,"Até 10 agendamentos por mês","Suporte prioritário e até 10 agendamentos por mês"));}
 private Map<String,Object> plano(String id,String nome,double preco,int limite,String uso,String beneficio){return Map.of("id",id,"nome",nome,"precoMensal",preco,"limiteMensal",limite,"uso",uso,"beneficio",beneficio);}
 @GetMapping("/minha") public Map<String,Object> minha(Authentication a){PaiResponsavel p=pai(a.getName()); AssinaturaPai x=repo.findByPaiId(p.getId()).orElseGet(()->{AssinaturaPai n=new AssinaturaPai();n.setPai(p);return repo.save(n);}); return Map.of("plano",x.getPlano(),"status",x.getStatus(),"inicio",x.getInicio(),"fim",x.getFim()==null?"":x.getFim(),"atualizadoEm",x.getAtualizadoEm(),"cobrancaReal",false);}
 @PostMapping("/assinar") public Map<String,Object> assinar(@RequestBody Map<String,String> body,Authentication a){PaiResponsavel p=pai(a.getName());String plano=body.getOrDefault("plano","GRATUITO");if(!Set.of("GRATUITO","FAMILIA","FAMILIA_PLUS").contains(plano))throw new IllegalArgumentException("Plano inválido.");AssinaturaPai x=repo.findByPaiId(p.getId()).orElseGet(()->{AssinaturaPai n=new AssinaturaPai();n.setPai(p);return n;});x.setPlano(plano);x.setStatus("ATIVO");x.setInicio(LocalDate.now());x.setFim(null);x.setAtualizadoEm(LocalDateTime.now());repo.save(x);return Map.of("plano",x.getPlano(),"status",x.getStatus(),"cobrancaReal",false,"mensagem",plano.equals("GRATUITO")?"Plano gratuito ativado.":"Plano de demonstração ativado. Nenhuma cobrança foi realizada.");}

 @GetMapping("/fidelidade") public Map<String,Object> fidelidade(Authentication a){PaiResponsavel p=pai(a.getName());long concluidos=agendamentos.findByPaiIdOrderByDataServicoDesc(p.getId()).stream().filter(g->g.getStatus()==StatusAgendamento.CONCLUIDO).count();long pontos=concluidos*10;String nivel=pontos>=200?"Ouro":pontos>=80?"Prata":pontos>=20?"Bronze":"Iniciante";return Map.of("atendimentosConcluidos",concluidos,"pontos",pontos,"nivel",nivel,"regra","10 pontos por atendimento concluído. Pontos demonstrativos, sem valor monetário.");}
 @PostMapping("/cancelar") public Map<String,Object> cancelar(Authentication a){PaiResponsavel p=pai(a.getName());AssinaturaPai x=repo.findByPaiId(p.getId()).orElseThrow(()->new IllegalArgumentException("Nenhuma assinatura ativa."));x.setPlano("GRATUITO");x.setStatus("ATIVO");x.setFim(LocalDate.now());x.setAtualizadoEm(LocalDateTime.now());repo.save(x);return Map.of("plano","GRATUITO","mensagem","Você voltou ao plano gratuito. Nenhuma cobrança foi realizada.");}
}
